            <p className={`${isDark ? 'text-slate-400' : 'text-slate-500'} text-sm font-bold`}>مشروعك <span className={`${activeGlobalTheme.accent} transition-colors duration-500`}>"{user.startupName}"</span> في مسار التطوير.</p>
          </div>

