export const evaluateNominationForm = async (data: NominationData): Promise<NominationResult> => {
  const prompt = `حلل بيانات التقدم لمسرعة الأعمال التالية:
  - اسم المشروع: ${data.companyName}
  - المشكلة: ${data.problemStatement}
