  { value: 'Other', label: 'أخرى' }
];

export const Registration: React.FC<RegistrationProps> = ({ onRegister, onStaffLogin }) => {
  const [formData, setFormData] = useState<UserProfile>({
    firstName: '',
    lastName: '',
    startupName: '',
    startupDescription: '',
    industry: 'Technology',
    phone: '',
    email: '',
    age: 0,
    birthDate: '',
    foundationYear: new Date().getFullYear(),
    foundersCount: 1,
    technologies: '',
    agreedToTerms: false,
    signedContractName: ''
  });

  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<ProjectEvaluationResult | null>(null);
  const [showLegal, setShowLegal] = useState(false);

  const validate = (): boolean => {
    const newErrors: Record<string, string> = {};
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const phoneRegex = /^(05|5)\d{8}$/;

    if (!formData.firstName.trim()) newErrors.firstName = 'الاسم الأول مطلوب';
    if (!formData.lastName.trim()) newErrors.lastName = 'اللقب مطلوب';
    if (!formData.email.trim() || !emailRegex.test(formData.email)) newErrors.email = 'بريد إلكتروني غير صحيح';
    if (!formData.phone.trim() || !phoneRegex.test(formData.phone.replace(/\s/g, ''))) newErrors.phone = 'رقم جوال غير صحيح';
    if (!formData.startupName.trim()) newErrors.startupName = 'اسم المشروع مطلوب';
    if (!formData.startupDescription.trim() || formData.startupDescription.length < 20) newErrors.startupDescription = 'يرجى كتابة وصف مفصل';

    // Legal Validations
    if (!formData.agreedToTerms) newErrors.agreedToTerms = 'يجب الموافقة على الشروط والأحكام';
    if (!formData.signedContractName || formData.signedContractName !== `${formData.firstName} ${formData.lastName}`) {
      newErrors.signedContractName = 'يجب كتابة اسمك الكامل للتوقيع على العقد';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleAnalyzeIdea = async () => {
    if (!formData.startupDescription || formData.startupDescription.length < 20) {
      setErrors(prev => ({ ...prev, startupDescription: 'الوصف قصير جداً للتحليل' }));
      return;
    }
    setIsAnalyzing(true);
    try {
      const tempProfile: ApplicantProfile = {
        codeName: `${formData.firstName} ${formData.lastName}`,
        projectStage: 'Idea',
        sector: formData.industry,
        goal: 'Initial Analysis',
        techLevel: 'Medium'
      };
      const result = await evaluateProjectIdea(formData.startupDescription, tempProfile);
      setAnalysisResult(result);
      playCelebrationSound();
    } catch (e) {
      playErrorSound();
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (validate()) {
      onRegister({
        ...formData,
        contractSignedAt: new Date().toISOString()
      });
    } else {
      playErrorSound();
    }
  };

  return (
    <div className="min-h-screen flex bg-slate-950 font-sans text-white" dir="rtl">
      <style>{`
        .legal-scroll::-webkit-scrollbar { width: 4px; }
        .legal-scroll::-webkit-scrollbar-thumb { background: #3b82f6; border-radius: 10px; }
      `}</style>

      {/* Side Panel */}
      <div className="hidden lg:flex lg:w-1/3 relative bg-slate-900 flex-col justify-between p-12 text-white border-l border-white/5">
        <div className="relative z-10">
          <div className="flex items-center gap-3 mb-10">
            <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center border border-white/20 shadow-2xl">
              <svg className="w-7 h-7 text-white" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5" /></svg>
            </div>
            <span className="text-2xl font-black uppercase tracking-tighter">AI Accelerator</span>
          </div>
          <h1 className="text-5xl font-black leading-tight mb-6">منصة <br/><span className="text-blue-500">العقود الذكية.</span></h1>
          <p className="text-lg text-slate-400 max-w-xs">نضمن لك بيئة ريادية آمنة، تبدأ بشروط واضحة وتنتهي بنجاح باهر.</p>
        </div>

        <div className="relative z-10">
           <div className="bg-blue-600/10 border border-blue-500/20 p-6 rounded-3xl backdrop-blur-md">
              <h4 className="text-blue-400 font-black text-xs uppercase tracking-widest mb-2">تنبيه قانوني</h4>
              <p className="text-[11px] text-slate-300 leading-relaxed">بإتمامك لعملية التسجيل، أنت تدخل في اتفاقية احتضان رسمية مع مسرعة بيزنس ديفلوبرز، مما يضمن حقوقك وحقوق المنصة.</p>
           </div>
        </div>
      </div>

      {/* Form Area */}
      <div className="w-full lg:w-2/3 flex flex-col p-6 md:p-12 overflow-y-auto bg-slate-950">
        <div className="max-w-3xl w-full mx-auto animate-fade-in-up">
          <header className="mb-12">
            <h2 className="text-4xl font-black mb-2">تسجيل رائد أعمال</h2>
            <p className="text-slate-400">الرجاء تعبئة البيانات والقيام بتوقيع عقد الاحتضان.</p>
          </header>

          <form onSubmit={handleSubmit} className="space-y-12 pb-20">
            {/* Basic Info */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-500 uppercase tracking-widest">الاسم الأول</label>
                <input className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl outline-none focus:border-blue-500" value={formData.firstName} onChange={e => setFormData({...formData, firstName: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-500 uppercase tracking-widest">اللقب</label>
                <input className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl outline-none focus:border-blue-500" value={formData.lastName} onChange={e => setFormData({...formData, lastName: e.target.value})} />
              </div>
              <div className="md:col-span-2 space-y-2">
                <label className="text-xs font-black text-slate-500 uppercase tracking-widest">اسم المشروع</label>
                <input className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl outline-none focus:border-blue-500" value={formData.startupName} onChange={e => setFormData({...formData, startupName: e.target.value})} />
              </div>
              <div className="md:col-span-2 space-y-2">
                <label className="text-xs font-black text-slate-500 uppercase tracking-widest">وصف الفكرة</label>
                <textarea className="w-full h-32 p-4 bg-white/5 border border-white/10 rounded-2xl outline-none focus:border-blue-500 resize-none" value={formData.startupDescription} onChange={e => setFormData({...formData, startupDescription: e.target.value})} />
                <button type="button" onClick={handleAnalyzeIdea} disabled={isAnalyzing} className="text-[10px] font-black text-blue-500 hover:text-blue-400 uppercase tracking-widest">
                   {isAnalyzing ? 'جاري التحليل...' : '✨ تحليل مبدئي للفكرة'}
                </button>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-500 uppercase tracking-widest">الايميل</label>
                <input type="email" className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl outline-none focus:border-blue-500" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-500 uppercase tracking-widest">الجوال</label>
                <input className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl outline-none focus:border-blue-500" placeholder="05xxxxxxxx" value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} />
              </div>
            </div>

            {/* Legal Agreement Section */}
            <div className="pt-10 border-t border-white/5 space-y-8">
               <h3 className="text-xl font-black text-blue-500">الموافقة القانونية والتوقيع</h3>

               <div className="bg-slate-900 border border-white/10 rounded-[2rem] overflow-hidden">
                  <div className="p-6 border-b border-white/5 bg-white/5 flex justify-between items-center">
                     <span className="font-bold text-sm">اتفاقية شروط الاستخدام</span>
                     <span className="text-[10px] text-slate-500 font-bold uppercase">Legal Document v4.0</span>
                  </div>
                  <div className="p-6 h-40 overflow-y-auto legal-scroll text-xs text-slate-400 leading-relaxed font-medium">
                     نحن مسرعة بيزنس ديفلوبرز نلتزم بتقديم أفضل الأدوات التدريبية والتقارير المبنية على الذكاء الاصطناعي.
                     1. يلتزم رائد الأعمال بصحة كافة البيانات المدخلة.
                     2. جميع التقارير الصادرة من المنصة هي أدوات استشارية وليست ضمانات مالية.
                     3. يتم تشفير بياناتك وضمان خصوصيتها بنسبة 100%.
                     4. لا يحق للمستخدم إعادة بيع المحتوى التعليمي للمسرعة.
                     5. تحتفظ المسرعة بحق إلغاء الاشتراك في حال مخالفة الآداب العامة.
                     6. الموافقة على مشاركة مؤشرات الأداء (KPIs) مع فريق التوجيه.
                  </div>
                  <div className="p-6 bg-blue-600/5 flex items-center gap-3">
                     <input 
                        type="checkbox" 
                        id="terms"
                        checked={formData.agreedToTerms} 
                        onChange={e => setFormData({...formData, agreedToTerms: e.target.checked})}
                        className="w-5 h-5 accent-blue-600 cursor-pointer"
                     />
                     <label htmlFor="terms" className="text-sm font-bold cursor-pointer select-none">أوافق على الشروط والأحكام المذكورة أعلاه</label>
                  </div>
               </div>

               {/* Incubation Contract Signature */}
               <div className="bg-white text-slate-900 p-8 md:p-10 rounded-[2.5rem] shadow-2xl relative overflow-hidden">
                  <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500 opacity-5 rounded-bl-full"></div>
                  <div className="text-center mb-8">
                     <h4 className="text-2xl font-black">عقد احتضان مشروع ناشئ</h4>
