  { id: 'events', label: 'الفعاليات', icon: '🚀', section: 'main' },

  { id: 'bootcamp', label: 'المعسكر التدريبي', icon: '🚀', section: 'program' },
  { id: 'program_manager', label: 'مدير البرنامج', icon: '👥', section: 'program' },
