          100% { transform: translateX(-100%); }
        }
        .animate-progress-shimmer { animation: progress-shimmer 2s infinite linear; }
        @keyframes data-fly {
          0% { transform: translate(0, 0); opacity: 0; }
          20% { opacity: 1; }
          80% { opacity: 1; }
          100% { transform: translate(var(--tx), var(--ty)); opacity: 0; }
        }
        @keyframes scanning {
          0% { transform: translateY(-50px); opacity: 0; }
          50% { opacity: 1; }
          100% { transform: translateY(150px); opacity: 0; }
        }
        .animate-scanning { animation: scanning 3s linear infinite; }
        .hide-axis .recharts-cartesian-axis { display: none; }

        .content-card-enter { opacity: 0; transform: translateX(20px); }
        .content-card-enter-active { opacity: 1; transform: translateX(0); transition: all 0.5s ease-out; }
      `}</style>

