                    </svg>
                  </div>
                  <p className="font-black text-slate-300">اضغط لرفع ملف العرض التوضيحي</p>
                  <p className="text-[10px] text-slate-500 mt-2 font-bold uppercase tracking-widest">PDF, DOCX, PPTX (MAX 10MB)</p>
               </div>
             )}

             <div className="mt-10">
               <button 
                 onClick={handleAnalyze}
