                   </>
                 ) : (
                   <>
                     <span className="text-xl">تفعيل التحقق من الفكرة</span>
                     <svg className="w-6 h-6 group-hover:translate-x-[-6px] transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
