                        <p className="text-blue-100 text-sm max-w-xl mx-auto font-medium">مشروعك الآن يمتلك الجاهزية الكافية لمقابلة المستثمرين وبدء جولات التمويل.</p>
                        <button onClick={onShowCertificate} className="mt-4 px-10 py-4 bg-white text-blue-900 rounded-2xl font-black text-sm shadow-xl hover:scale-105 transition-all active:scale-95">عرض وثيقة التخرج</button>
                     </div>
                  </div>
                )}
             </div>
           )}

           {activeNav !== 'home' && (
             <div className="flex flex-col items-center justify-center h-full text-center py-20 opacity-30 select-none">
                <div className="text-9xl mb-8 animate-float">🛠️</div>
                <h3 className="text-3xl font-black mb-4">قيد التطوير</h3>
                <p className="text-lg font-bold max-w-md mx-auto leading-relaxed">هذه الميزة ستتوفر قريباً في التحديث القادم لمنصة بيزنس ديفلوبرز الذكية.</p>
             </div>
           )}
        </div>
      </main>
    </div>
  );
};

