                       dataKey="value" 
                       stroke={activeTheme.primary.includes('blue') ? '#3b82f6' : activeTheme.primary.includes('emerald') ? '#10b981' : activeTheme.primary.includes('indigo') ? '#6366f1' : '#f43f5e'} 
                       strokeWidth={2} 
