                                </div>
                              )}
                           </div>

                           {/* Mobile arrow indicator */}
                           <div className="sm:hidden text-slate-300">
                              <svg className="w-4 h-4 transform rotate-180" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}><path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7" /></svg>
                           </div>
                        </div>
                      ))}
                   </div>
                </div>

                {progress === 100 && (
                  <div className="bg-gradient-to-r from-blue-600 to-indigo-700 p-8 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden text-center group">
                     <div className="absolute inset-0 bg-white/5 opacity-0 group-hover:opacity-100 transition-opacity"></div>
                     <div className="relative z-10 space-y-4">
                        <div className="text-4xl mb-2 animate-bounce">🎓</div>
                        <h3 className="text-3xl font-black">تهانينا! لقد تخرجت بنجاح</h3>
                        <p className="text-blue-100 text-sm max-w-xl mx-auto font-medium">مشروعك الآن يمتلك الجاهزية الكافية لمقابلة المستثمرين وبدء جولات التمويل.</p>
                        <button onClick={onShowCertificate} className="mt-4 px-10 py-4 bg-white text-blue-900 rounded-2xl font-black text-sm shadow-xl hover:scale-105 transition-all active:scale-95">عرض وثيقة التخرج</button>
                     </div>
                  </div>
                )}
             </div>
           )}

           {activeNav !== 'home' && (
