    const items = contentBlocks.map((b, i) => ({ type: 'content' as const, data: b, index: i }));
    items.push({ type: 'resources' as const, data: '', index: contentBlocks.length });
    return items;
  }, [contentBlocks]);

  // Chart Data for Progress
