           )}
        </div>
      </main>

      {/* Customizer Modal */}
      {isCustomizerOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-md animate-fade-in" dir="rtl">
